extern "C" {


static inline void abpoa_res_copy(abpoa_res_t *dest, abpoa_res_t *src) {
    int i;
    if (dest->n_cigar) free(dest->graph_cigar);
    dest->n_cigar = src->n_cigar;
    dest->graph_cigar = (uint64_t*)err_malloc(__func__, src->n_cigar * sizeof(uint64_t));
    for (i = 0; i < src->n_cigar; ++i) dest->graph_cigar[i] = src->graph_cigar[i];
    dest->node_s = src->node_s, dest->node_e = src->node_e;
    dest->query_s = src->query_s, dest->query_e = src->query_e;
    dest->n_aln_bases = src->n_aln_bases, dest->n_matched_bases = src->n_matched_bases;
    dest->best_score = src->best_score;

}

static inline uint64_t *abpoa_push_cigar(int *n_cigar, int *m_cigar, uint64_t *cigar, int op, int len, int32_t node_id, int32_t query_id) {
    uint64_t l = len;
    if (*n_cigar == 0 || (op != 1 && op != 4 && op != 5) || op != (int)(cigar[(*n_cigar)-1] & 0xf)) {
        if (*n_cigar == *m_cigar) {
            *m_cigar = *m_cigar? (*m_cigar)<<1 : 4;
            cigar = (uint64_t*)err_realloc(__func__, cigar, (*m_cigar) * sizeof(uint64_t));
        }
        uint64_t n_id = node_id, q_id = query_id;
        if (op == 0 || op == 3)
            cigar[(*n_cigar)++] = n_id << 34 | q_id << 4 | op;
        else if (op == 1 || op == 4 || op == 5)
            cigar[(*n_cigar)++] = q_id << 34 | l << 4 | op;
        else if (op == 2)
            cigar[(*n_cigar)++] = n_id << 34 | l << 4 | op;
        else
            err_fatal(__func__, "Unknown cigar operation: %s\n", op);
    } else cigar[(*n_cigar)-1] += l << 4;

    return cigar;
}

static inline int abpoa_push_whole_cigar(int *dest_n_cigar, int *dest_m_cigar, uint64_t **dest_cigar, int src_n_cigar, uint64_t *src_cigar) {
    int i, dest_n_c = *dest_n_cigar;
    *dest_n_cigar += src_n_cigar;
    if (*dest_n_cigar > *dest_m_cigar) {
        *dest_m_cigar = (((*dest_m_cigar) << 1) > (*dest_n_cigar) ? ((*dest_m_cigar) << 1) : (*dest_n_cigar));
        *dest_cigar = (uint64_t*)err_realloc(__func__, *dest_cigar, *dest_m_cigar * sizeof(uint64_t));
    }
    for (i = 0; i < src_n_cigar; ++i) {
        (*dest_cigar)[dest_n_c+i] = src_cigar[i];
    }
    return 0;
}

static inline uint64_t *abpoa_reverse_cigar(int n_cigar, uint64_t *cigar) {
    int i; uint64_t tmp;
    for (i = 0; i < n_cigar >> 1; ++i) {
        tmp = cigar[i];
        cigar[i] = cigar[n_cigar-1-i];
        cigar[n_cigar-1-i] = tmp;
    }
    return cigar;
}

static inline void abpoa_print_cigar(int n_cigar, uint64_t *cigar, abpoa_graph_t *graph) {
    int i, node_id, query_id, index_i; int op, len;
    int n[6] = {0, 0, 0, 0, 0, 0};
    for (i = 0; i < n_cigar; ++i) {
        op = cigar[i] & 0xf; node_id = (int)(cigar[i] >> 34);
        len = query_id = (int)(cigar[i] >> 4) & 0x3fffffff;
        if (op == 0 || op == 3) {
            index_i = abpoa_graph_node_id_to_index(graph, node_id);
            printf("1%c:%d,%d\t", "MIDXSH"[op], index_i, query_id);
            n[op] += 1;
        } else if (op == 2) {
            index_i = abpoa_graph_node_id_to_index(graph, node_id);
            printf("%d%c:%d\t", len, "MIDXSH"[op], index_i);
            n[op] += len;
        } else if (op == 1 || op == 4 || op == 5) {
            query_id = node_id;
            printf("%d%c:%d\t", len, "MIDXSH"[op], query_id);
            n[op] += len;
        } else {
            err_fatal(__func__, "Unknown cigar operation: %s\n", op);
        }
    } printf("\n");
    for (i = 0; i < 6; ++i)
        printf("%d%c ", n[i], "MIDXSH"[i]);
    printf("\n");
}


}
