}

enum {
    GPU_STATE_M = 0,
    GPU_STATE_E1 = 1,
    GPU_STATE_E2 = 2,
    GPU_STATE_F1 = 3,
    GPU_STATE_F2 = 4
};

__attribute__((host)) __attribute__((device)) static inline size_t gpu_cell(int idx, int j, int qcols) {
    return (size_t)idx * (size_t)qcols + (size_t)j;
}

__attribute__((host)) __attribute__((device)) static inline int gpu_max2(int a, int b) {
    return a > b ? a : b;
}

static __attribute__((constant)) int d_mat_const[1024];
__attribute__((device)) static inline int gpu_score_pair(int *mat, int m, uint8_t a, uint8_t b) {
    return mat[(int)a * m + (int)b];
}

__attribute__((device)) static inline int gpu_cell_in_band(int idx, int j, int qlen, int n_nodes,
                                             int source_index, int sink_index, int band) {
    if (band <= 0 || idx == source_index || idx == sink_index) return 1;
    int denom = n_nodes > 2 ? n_nodes - 2 : n_nodes;
    int center = (int)(((long long)idx * (long long)qlen + denom / 2) / denom);
    int delta = j - center;
    return delta >= -band && delta <= band;
}

__attribute__((device)) static inline int gpu_score_valid(int v) {
    return v > (-1000000000) / 2;
}

__attribute__((device)) static inline int gpu_gap_out_score(int h, int e, int gap_oe, int gap_ext) {
    int best = (-1000000000);
    if (gpu_score_valid(e)) best = e - gap_ext;
    if (gpu_score_valid(h)) {
        int cand = h - gap_oe;
        if (cand > best) best = cand;
    }
    return best;
}

__attribute__((device)) static inline uint64_t gpu_make_cigar(int op, int len, int32_t node_id, int32_t query_id) {
    uint64_t l = (uint64_t)len;
    uint64_t n_id = (uint64_t)(uint32_t)node_id;
    uint64_t q_id = (uint64_t)(uint32_t)query_id;
    if (op == 0 || op == 3) return n_id << 34 | q_id << 4 | (uint64_t)op;
    if (op == 1 || op == 4 || op == 5) return q_id << 34 | l << 4 | (uint64_t)op;
    return n_id << 34 | l << 4 | (uint64_t)op;
}

__attribute__((global)) void abpoa_gpu_dp_kernel(
        int n_nodes, int qlen, int qcols, int source_index, int sink_index,
        const uint8_t *query, const uint8_t *bases, const int *mat, int m,
        const int *pred_offsets, const int *preds,
        int gap_open1, int gap_open2, int gap_ext1, int gap_ext2,
        int *dp_e1, int *dp_e2, int *dp_f1, int *dp_f2, int *dp_h,
        int *best_score, int *best_index) {
    if (blockIdx.x != 0) return;
    int tid = threadIdx.x, stride = blockDim.x;

    size_t total = (size_t)n_nodes * (size_t)qcols;
    for (size_t i = (size_t)tid; i < total; i += (size_t)stride) {
        dp_e1[i] = dp_e2[i] = dp_f1[i] = dp_f2[i] = dp_h[i] = (-1000000000);
    }
    __syncthreads();

    int gap_oe1 = gap_open1 + gap_ext1;
    int gap_oe2 = gap_open2 + gap_ext2;
    if (tid == 0) {
        size_t c0 = gpu_cell(source_index, 0, n_nodes);
        dp_h[c0] = 0;
        dp_e1[c0] = -gap_oe1;
        dp_e2[c0] = gap_open2 > 0 ? -gap_oe2 : (-1000000000);
    }
    for (int j = tid + 1; j <= qlen; j += stride) {
        size_t c = gpu_cell(source_index, j, n_nodes);
        int s1 = -(gap_open1 + gap_ext1 * j);
        int s2 = gap_open2 > 0 ? -(gap_open2 + gap_ext2 * j) : (-1000000000);
        dp_h[c] = gpu_max2(s1, s2);
        dp_f1[c] = s1;
        dp_f2[c] = s2;
    }
    __syncthreads();

    int max_diag = n_nodes - 1 + qlen;
    for (int diag = 0; diag <= max_diag; ++diag) {
        int idx_beg = diag - qlen;
        if (idx_beg < 0) idx_beg = 0;
        int idx_end = diag;
        if (idx_end >= n_nodes) idx_end = n_nodes - 1;
        int diag_n = idx_end - idx_beg + 1;
        for (int off = tid; off < diag_n; off += stride) {
            int idx = idx_beg + off;
            int j = diag - idx;
            if (idx == source_index || idx == sink_index) continue;
            int p_beg = pred_offsets[idx], p_end = pred_offsets[idx + 1];
            int p_n = p_end - p_beg;
            size_t cur = gpu_cell(idx, j, n_nodes);

            int best_e1 = (-1000000000), best_e2 = (-1000000000);
            if (p_n == 1) {
                int pred = preds[p_beg];
                size_t pc = gpu_cell(pred, j, n_nodes);
                int h_pc = dp_h[pc];
                int e1_pc = dp_e1[pc];
                if (h_pc > (-1000000000) / 2) {
                    int cand = h_pc - gap_oe1;
                    if (cand > best_e1) best_e1 = cand;
                }
                if (e1_pc > (-1000000000) / 2) {
                    int cand = e1_pc - gap_ext1;
                    if (cand > best_e1) best_e1 = cand;
                }
                if (gap_open2 > 0) {
                    int e2_pc = dp_e2[pc];
                    if (h_pc > (-1000000000) / 2) {
                        int cand = h_pc - gap_oe2;
                        if (cand > best_e2) best_e2 = cand;
                    }
                    if (e2_pc > (-1000000000) / 2) {
                        int cand = e2_pc - gap_ext2;
                        if (cand > best_e2) best_e2 = cand;
                    }
                }
            } else {
                for (int k = p_beg; k < p_end; ++k) {
                    int pred = preds[k];
                    size_t pc = gpu_cell(pred, j, n_nodes);
                    int h_pc = dp_h[pc];
                    int e1_pc = dp_e1[pc];
                    if (h_pc > (-1000000000) / 2) {
                        int cand = h_pc - gap_oe1;
                        if (cand > best_e1) best_e1 = cand;
                    }
                    if (e1_pc > (-1000000000) / 2) {
                        int cand = e1_pc - gap_ext1;
                        if (cand > best_e1) best_e1 = cand;
                    }
                    if (gap_open2 > 0) {
                        int e2_pc = dp_e2[pc];
                        if (h_pc > (-1000000000) / 2) {
                            int cand = h_pc - gap_oe2;
                            if (cand > best_e2) best_e2 = cand;
                        }
                        if (e2_pc > (-1000000000) / 2) {
                            int cand = e2_pc - gap_ext2;
                            if (cand > best_e2) best_e2 = cand;
                        }
                    }
                }
            }
            dp_e1[cur] = best_e1;
            dp_e2[cur] = best_e2;

            int best_m = (-1000000000), best_f1 = (-1000000000), best_f2 = (-1000000000);
            if (j > 0) {
                int s = d_mat_const[(int)bases[idx] * m + (int)query[j - 1]];
                if (p_n == 1) {
                    int pred = preds[p_beg];
                    int h_pc = dp_h[gpu_cell(pred, j - 1, n_nodes)];
                    if (h_pc > (-1000000000) / 2) {
                        int cand = h_pc + s;
                        if (cand > best_m) best_m = cand;
                    }
                } else {
                    for (int k = p_beg; k < p_end; ++k) {
                        int pred = preds[k];
                        int h_pc = dp_h[gpu_cell(pred, j - 1, n_nodes)];
                        if (h_pc > (-1000000000) / 2) {
                            int cand = h_pc + s;
                            if (cand > best_m) best_m = cand;
                        }
                    }
                }

                size_t left = gpu_cell(idx, j - 1, n_nodes);
                int h_left = dp_h[left];
                int f1_left = dp_f1[left];
                if (h_left > (-1000000000) / 2) {
                    best_f1 = h_left - gap_oe1;
                }
                if (f1_left > (-1000000000) / 2) {
                    int cand = f1_left - gap_ext1;
                    if (cand > best_f1) best_f1 = cand;
                }
                if (gap_open2 > 0) {
                    int f2_left = dp_f2[left];
                    if (h_left > (-1000000000) / 2) {
                        best_f2 = h_left - gap_oe2;
                    }
                    if (f2_left > (-1000000000) / 2) {
                        int cand = f2_left - gap_ext2;
                        if (cand > best_f2) best_f2 = cand;
                    }
                }
            }
            dp_f1[cur] = best_f1;
            dp_f2[cur] = best_f2;

            int best_h = best_m;
            if (best_e1 > best_h) best_h = best_e1;
            if (best_e2 > best_h) best_h = best_e2;
            if (best_f1 > best_h) best_h = best_f1;
            if (best_f2 > best_h) best_h = best_f2;
            dp_h[cur] = best_h;
        }
        __syncthreads();
    }

    if (tid == 0) {
        int best = (-1000000000), best_idx = source_index;
        int s_beg = pred_offsets[sink_index], s_end = pred_offsets[sink_index + 1];
        for (int k = s_beg; k < s_end; ++k) {
            int pred = preds[k];
            int h = dp_h[gpu_cell(pred, qlen, n_nodes)];
            if (h > best) {
                best = h;
                best_idx = pred;
            }
        }
        *best_score = best;
        *best_index = best_idx;
    }
}

__attribute__((global)) void abpoa_gpu_dp_batch_kernel(
        int batch_n, int n_nodes, int max_qlen, int qcols, int source_index, int sink_index,
        const uint8_t *queries, const int *qlens, const uint8_t *bases, const int *mat, int m,
        const int *pred_offsets, const int *preds,
        int gap_open1, int gap_open2, int gap_ext1, int gap_ext2,
        int band,
        int *dp_e1_all, int *dp_e2_all, int *dp_f1_all, int *dp_f2_all, int *dp_h_all,
        int *best_scores, int *best_indices) {
    int b = blockIdx.x;
    if (b >= batch_n) return;

    int qlen = qlens[b];
    size_t cells = (size_t)n_nodes * (size_t)qcols;
    const uint8_t *query = queries + (size_t)b * (size_t)max_qlen;
    int *dp_e1 = dp_e1_all + (size_t)b * cells;
    int *dp_e2 = dp_e2_all + (size_t)b * cells;
    int *dp_f1 = dp_f1_all + (size_t)b * cells;
    int *dp_f2 = dp_f2_all + (size_t)b * cells;
    int *dp_h = dp_h_all + (size_t)b * cells;
    int tid = threadIdx.x, stride = blockDim.x;

    size_t total = (size_t)n_nodes * (size_t)qcols;
    for (size_t i = (size_t)tid; i < total; i += (size_t)stride) {
        dp_e1[i] = dp_e2[i] = dp_f1[i] = dp_f2[i] = dp_h[i] = (-1000000000);
    }
    __syncthreads();

    int gap_oe1 = gap_open1 + gap_ext1;
    int gap_oe2 = gap_open2 + gap_ext2;
    if (tid == 0) {
        size_t c0 = gpu_cell(source_index, 0, n_nodes);
        dp_h[c0] = 0;
        dp_e1[c0] = -gap_oe1;
        dp_e2[c0] = gap_open2 > 0 ? -gap_oe2 : (-1000000000);
    }
    for (int j = tid + 1; j <= qlen; j += stride) {
        size_t c = gpu_cell(source_index, j, n_nodes);
        int s1 = -(gap_open1 + gap_ext1 * j);
        int s2 = gap_open2 > 0 ? -(gap_open2 + gap_ext2 * j) : (-1000000000);
        dp_h[c] = gpu_max2(s1, s2);
        dp_f1[c] = s1;
        dp_f2[c] = s2;
    }
    __syncthreads();

    int max_diag = n_nodes - 1 + qlen;
    for (int diag = 0; diag <= max_diag; ++diag) {
        int idx_beg = diag - qlen;
        if (idx_beg < 0) idx_beg = 0;
        int idx_end = diag;
        if (idx_end >= n_nodes) idx_end = n_nodes - 1;
        int diag_n = idx_end - idx_beg + 1;
        for (int off = tid; off < diag_n; off += stride) {
            int idx = idx_beg + off;
            int j = diag - idx;
            if (idx == source_index || idx == sink_index) continue;
            if (!gpu_cell_in_band(idx, j, qlen, n_nodes, source_index, sink_index, band)) continue;
            int p_beg = pred_offsets[idx], p_end = pred_offsets[idx + 1];
            size_t cur = gpu_cell(idx, j, n_nodes);

            int best_e1 = (-1000000000), best_e2 = (-1000000000);
            for (int k = p_beg; k < p_end; ++k) {
                int pred = preds[k];
                if (!gpu_cell_in_band(pred, j, qlen, n_nodes, source_index, sink_index, band)) continue;
                size_t pc = gpu_cell(pred, j, n_nodes);
                int h_pc = dp_h[pc];
                int e1_pc = dp_e1[pc];
                if (h_pc > (-1000000000) / 2) {
                    int cand = h_pc - gap_oe1;
                    if (cand > best_e1) best_e1 = cand;
                }
                if (e1_pc > (-1000000000) / 2) {
                    int cand = e1_pc - gap_ext1;
                    if (cand > best_e1) best_e1 = cand;
                }
                if (gap_open2 > 0) {
                    int e2_pc = dp_e2[pc];
                    if (h_pc > (-1000000000) / 2) {
                        int cand = h_pc - gap_oe2;
                        if (cand > best_e2) best_e2 = cand;
                    }
                    if (e2_pc > (-1000000000) / 2) {
                        int cand = e2_pc - gap_ext2;
                        if (cand > best_e2) best_e2 = cand;
                    }
                }
            }
            dp_e1[cur] = best_e1;
            dp_e2[cur] = best_e2;

            int best_m = (-1000000000), best_f1 = (-1000000000), best_f2 = (-1000000000);
            if (j > 0) {
                int s = d_mat_const[(int)bases[idx] * m + (int)query[j - 1]];
                for (int k = p_beg; k < p_end; ++k) {
                    int pred = preds[k];
                    if (!gpu_cell_in_band(pred, j - 1, qlen, n_nodes, source_index, sink_index, band)) continue;
                    int h_pc = dp_h[gpu_cell(pred, j - 1, n_nodes)];
                    if (h_pc > (-1000000000) / 2) {
                        int cand = h_pc + s;
                        if (cand > best_m) best_m = cand;
                    }
                }

                int h_left = (-1000000000), f1_left = (-1000000000);
                if (gpu_cell_in_band(idx, j - 1, qlen, n_nodes, source_index, sink_index, band)) {
                    size_t left = gpu_cell(idx, j - 1, n_nodes);
                    h_left = dp_h[left];
                    f1_left = dp_f1[left];
                }
                if (h_left > (-1000000000) / 2) {
                    best_f1 = h_left - gap_oe1;
                }
                if (f1_left > (-1000000000) / 2) {
                    int cand = f1_left - gap_ext1;
                    if (cand > best_f1) best_f1 = cand;
                }
                if (gap_open2 > 0) {
                    int f2_left = (-1000000000);
                    if (gpu_cell_in_band(idx, j - 1, qlen, n_nodes, source_index, sink_index, band)) {
                        f2_left = dp_f2[gpu_cell(idx, j - 1, n_nodes)];
                    }
                    if (h_left > (-1000000000) / 2) {
                        best_f2 = h_left - gap_oe2;
                    }
                    if (f2_left > (-1000000000) / 2) {
                        int cand = f2_left - gap_ext2;
                        if (cand > best_f2) best_f2 = cand;
                    }
                }
            }
            dp_f1[cur] = best_f1;
            dp_f2[cur] = best_f2;

            int best_h = best_m;
            if (best_e1 > best_h) best_h = best_e1;
            if (best_e2 > best_h) best_h = best_e2;
            if (best_f1 > best_h) best_h = best_f1;
            if (best_f2 > best_h) best_h = best_f2;
            dp_h[cur] = best_h;
        }
        __syncthreads();
    }

    if (tid == 0) {
        int best = (-1000000000), best_idx = source_index;
        int s_beg = pred_offsets[sink_index], s_end = pred_offsets[sink_index + 1];
        for (int k = s_beg; k < s_end; ++k) {
            int pred = preds[k];
            if (!gpu_cell_in_band(pred, qlen, qlen, n_nodes, source_index, sink_index, band)) continue;
            int h = dp_h[gpu_cell(pred, qlen, n_nodes)];
            if (h > best) {
                best = h;
                best_idx = pred;
            }
        }
        best_scores[b] = best;
        best_indices[b] = best_idx;
    }
}

__attribute__((device)) static inline int gpu_gap_out_i32(const int *dp_h, const int *dp_e,
                                             int idx, int j, int n_nodes,
                                             int gap_oe, int gap_ext) {
    size_t c = gpu_cell(idx, j, n_nodes);
    return gpu_gap_out_score(dp_h[c], dp_e[c], gap_oe, gap_ext);
}

__attribute__((device)) static inline int gpu_trace_match_i32(
        int *idx, int *j, int n_nodes, const uint8_t *query, const uint8_t *bases,
        const int *mat, int m, const int *node_ids, const int *pred_offsets, const int *preds,
        const int *dp_h, uint64_t *out_cigar, int *n_c) {
    if (*j <= 0) return 0;
    int h = dp_h[gpu_cell(*idx, *j, n_nodes)];
    int s = d_mat_const[(int)bases[*idx] * m + (int)query[*j - 1]];
    int p_beg = pred_offsets[*idx], p_end = pred_offsets[*idx + 1];
    for (int k = p_beg; k < p_end; ++k) {
        int pred = preds[k];
        int pred_h = dp_h[gpu_cell(pred, *j - 1, n_nodes)];
        if (gpu_score_valid(pred_h) && pred_h + s == h) {
            out_cigar[(*n_c)++] = gpu_make_cigar(0, 1, node_ids[*idx], *j - 1);
            *idx = pred;
            --(*j);
            return 1;
        }
    }
    return 0;
}

__attribute__((device)) static int gpu_traceback_cpu_style_i32(
        int qlen, int n_nodes, int source_index, int best_index,
        const uint8_t *query, const uint8_t *bases, const int *mat, int m,
        const int *node_ids, const int *pred_offsets, const int *preds,
        int gap_open1, int gap_open2, int gap_ext1, int gap_ext2,
        int put_gap_on_right, int put_gap_at_end,
        const int *dp_e1, const int *dp_e2, const int *dp_f1, const int *dp_f2, const int *dp_h,
        uint64_t *out_cigar, int max_cigar) {
    int idx = best_index, j = qlen;
    int n_c = 0;
    int cur_op = 0x1f;
    int look_for_first_gap_at_end = put_gap_at_end;
    int gap_oe1 = gap_open1 + gap_ext1;
    int gap_oe2 = gap_open2 + gap_ext2;

    while (idx != source_index && j > 0) {
        if (n_c >= max_cigar) return -1;
        int hit = 0;
        int h = dp_h[gpu_cell(idx, j, n_nodes)];

        if (put_gap_on_right == 0 && look_for_first_gap_at_end == 0 && (cur_op & 0x1)) {
            hit = gpu_trace_match_i32(&idx, &j, n_nodes, query, bases, mat, m, node_ids,
                                      pred_offsets, preds, dp_h, out_cigar, &n_c);
            if (hit) cur_op = 0x1f;
        }

        if (!hit && (cur_op & 0x6)) {
            int p_beg = pred_offsets[idx], p_end = pred_offsets[idx + 1];
            int cur_e1 = gpu_gap_out_i32(dp_h, dp_e1, idx, j, n_nodes, gap_oe1, gap_ext1);
            int cur_e2 = gap_open2 > 0 ? gpu_gap_out_i32(dp_h, dp_e2, idx, j, n_nodes, gap_oe2, gap_ext2) : (-1000000000);
            for (int k = p_beg; k < p_end && !hit; ++k) {
                int pred = preds[k];
                int pred_h = dp_h[gpu_cell(pred, j, n_nodes)];
                if (cur_op & 0x2) {
                    int pred_out = gpu_gap_out_i32(dp_h, dp_e1, pred, j, n_nodes, gap_oe1, gap_ext1);
                    int ok = (cur_op & 0x1) ? (h == pred_out) :
                             (gpu_score_valid(cur_e1) && gpu_score_valid(pred_out) && pred_out - gap_ext1 == cur_e1);
                    if (ok) {
                        cur_op = (gpu_score_valid(pred_h) && pred_h - gap_oe1 == pred_out) ? (0x1 | 0x18) : 0x2;
                        out_cigar[n_c++] = gpu_make_cigar(2, 1, node_ids[idx], j - 1);
                        idx = pred;
                        hit = 1;
                    }
                }
                if (!hit && (cur_op & 0x4)) {
                    int pred_out = gpu_gap_out_i32(dp_h, dp_e2, pred, j, n_nodes, gap_oe2, gap_ext2);
                    int ok = (cur_op & 0x1) ? (h == pred_out) :
                             (gpu_score_valid(cur_e2) && gpu_score_valid(pred_out) && pred_out - gap_ext2 == cur_e2);
                    if (ok) {
                        cur_op = (gpu_score_valid(pred_h) && pred_h - gap_oe2 == pred_out) ? (0x1 | 0x18) : 0x4;
                        out_cigar[n_c++] = gpu_make_cigar(2, 1, node_ids[idx], j - 1);
                        idx = pred;
                        hit = 1;
                    }
                }
            }
            if (hit && look_for_first_gap_at_end) look_for_first_gap_at_end = 0;
        }

        if (!hit && (cur_op & 0x18)) {
            size_t cur = gpu_cell(idx, j, n_nodes);
            size_t left = gpu_cell(idx, j - 1, n_nodes);
            if (cur_op & 0x8) {
                int f = dp_f1[cur];
                if ((cur_op & 0x1) == 0 || h == f) {
                    if (gpu_score_valid(dp_h[left]) && dp_h[left] - gap_oe1 == f) {
                        cur_op = 0x1 | 0x6;
                        hit = 1;
                    } else if (gpu_score_valid(dp_f1[left]) && dp_f1[left] - gap_ext1 == f) {
                        cur_op = 0x8;
                        hit = 1;
                    }
                }
            }
            if (!hit && (cur_op & 0x10)) {
                int f = dp_f2[cur];
                if ((cur_op & 0x1) == 0 || h == f) {
                    if (gpu_score_valid(dp_h[left]) && dp_h[left] - gap_oe2 == f) {
                        cur_op = 0x1 | 0x6;
                        hit = 1;
                    } else if (gpu_score_valid(dp_f2[left]) && dp_f2[left] - gap_ext2 == f) {
                        cur_op = 0x10;
                        hit = 1;
                    }
                }
            }
            if (hit) {
                out_cigar[n_c++] = gpu_make_cigar(1, 1, node_ids[idx], j - 1);
                --j;
                if (look_for_first_gap_at_end) look_for_first_gap_at_end = 0;
            }
        }

        if (!hit && (cur_op & 0x1)) {
            hit = gpu_trace_match_i32(&idx, &j, n_nodes, query, bases, mat, m, node_ids,
                                      pred_offsets, preds, dp_h, out_cigar, &n_c);
            if (hit) {
                cur_op = 0x1f;
                look_for_first_gap_at_end = 0;
            }
        }

        if (!hit) return -1;
    }

    while (j > 0) {
        if (n_c >= max_cigar) return -1;
        out_cigar[n_c++] = gpu_make_cigar(1, 1, -1, j - 1);
        --j;
    }
    return n_c;
}

__attribute__((global)) void abpoa_gpu_traceback_kernel(
        int qlen, int n_nodes, int source_index, int best_index,
        const uint8_t *query, const uint8_t *bases, const int *mat, int m,
        const int *node_ids, const int *pred_offsets, const int *preds,
        int gap_open1, int gap_open2, int gap_ext1, int gap_ext2,
        int put_gap_on_right, int put_gap_at_end,
        const int *dp_e1, const int *dp_e2, const int *dp_f1, const int *dp_f2, const int *dp_h,
        uint64_t *out_cigar, int max_cigar, int *out_n_cigar, int *out_status) {
    if (blockIdx.x != 0 || threadIdx.x != 0) return;
