static int cigar_node_id(uint64_t c) {
    return (int)(c >> 34);
}

static void trim_skippable_leading_deletions(abpoa_graph_t *graph, int *n_cigar, uint64_t *cigar) {
    while (*n_cigar > 1 && (int)(cigar[0] & 0xf) == 2) {
        int next_i = 1, next_node = -1;
        while (next_i < *n_cigar) {
            int op = (int)(cigar[next_i] & 0xf);
            if (op == 0 || op == 3 || op == 2) {
                next_node = cigar_node_id(cigar[next_i]);
                break;
            }
            ++next_i;
        }
        if (next_node < 0) break;


        (void)graph;
        memmove(cigar, cigar + 1, (size_t)(*n_cigar - 1) * sizeof(uint64_t));
        --(*n_cigar);
    }
}

