        gpu_set_error("failed to upload graph to CUDA device");
        return -1;
    }

    ctx->graph = graph;
    ctx->graph_sig = graph_sig;
    ctx->n_nodes = n_nodes;
    ctx->total_preds = total_preds;
    ctx->source_index = graph->node_id_to_index[0];
    ctx->sink_index = graph->node_id_to_index[1];

    if (abpt->verbose >= 1) {
        fprintf(
# 881 "src/abpoa_gpu.cu" 3 4
